select transaction_timestamp() as captured_at, current_setting('server_version') as postgres_version,(select jsonb_agg(to_jsonb(s)) from (select 'laundry_members' as table_name,count(*) as row_count,md5(coalesce(string_agg(to_jsonb(t)::text,'' order by to_jsonb(t)::text),'')) as checksum from public.laundry_members t union all select 'laundry_member_cards' as table_name,count(*) as row_count,md5(coalesce(string_agg(to_jsonb(t)::text,'' order by to_jsonb(t)::text),'')) as checksum from public.laundry_member_cards t union all select 'laundry_point_rules' as table_name,count(*) as row_count,md5(coalesce(string_agg(to_jsonb(t)::text,'' order by to_jsonb(t)::text),'')) as checksum from public.laundry_point_rules t union all select 'laundry_amount_transactions' as table_name,count(*) as row_count,md5(coalesce(string_agg(to_jsonb(t)::text,'' order by to_jsonb(t)::text),'')) as checksum from public.laundry_amount_transactions t union all select 'laundry_checklist_events' as table_name,count(*) as row_count,md5(coalesce(string_agg(to_jsonb(t)::text,'' order by to_jsonb(t)::text),'')) as checksum from public.laundry_checklist_events t union all select 'laundry_member_promotions' as table_name,count(*) as row_count,md5(coalesce(string_agg(to_jsonb(t)::text,'' order by to_jsonb(t)::text),'')) as checksum from public.laundry_member_promotions t union all select 'laundry_services' as table_name,count(*) as row_count,md5(coalesce(string_agg(to_jsonb(t)::text,'' order by to_jsonb(t)::text),'')) as checksum from public.laundry_services t)s) as data_fingerprints,(select jsonb_agg(jsonb_build_object('year',program_year,'revision',revision,'tiers',tiers) order by program_year)from public.laundry_point_rules)as point_rules,(select jsonb_agg(jsonb_build_object('schema',table_schema,'table',table_name,'column',column_name,'type',data_type,'nullable',is_nullable) order by table_schema,table_name,ordinal_position)from information_schema.columns where table_schema in('public','laundry_private') and table_name like 'laundry%')as columns,(select jsonb_agg(jsonb_build_object('schema',n.nspname,'name',p.proname,'args',pg_get_function_identity_arguments(p.oid),'definition_hash',md5(pg_get_functiondef(p.oid)),'security_definer',p.prosecdef,'config',p.proconfig,'acl',p.proacl::text)order by n.nspname,p.proname,p.oid)from pg_proc p join pg_namespace n on n.oid=p.pronamespace where (n.nspname='laundry_private' or(n.nspname='public' and p.proname like 'laundry%')) and p.prokind='f')as functions,(select jsonb_agg(to_jsonb(t) order by t.schemaname,t.tablename,t.policyname)from pg_policies t where t.schemaname in('public','laundry_private') and t.tablename like 'laundry%')as policies,(select jsonb_agg(jsonb_build_object('table',c.relname,'rls',c.relrowsecurity,'force_rls',c.relforcerowsecurity)order by c.relname)from pg_class c join pg_namespace n on n.oid=c.relnamespace where n.nspname='public' and c.relkind='r' and c.relname like 'laundry%')as table_security,(select jsonb_agg(jsonb_build_object('version',version,'name',name)order by version)from supabase_migrations.schema_migrations)as migration_history;
